import time
from abc import ABC, abstractmethod
from socket import error as socket_error

from websockets.exceptions import InvalidStatusCode


from taf.fdsw.rc.clients.exceptions import (ClientAuthenticationFailed,
                                            ClientConnectionFailed,
                                            ClientRequestFailed)
from taf.fdsw.rc.interfaces.exceptions import FunctionalityNotImplemented


class FDSW(ABC):

    @property
    @abstractmethod
    def _client(self):
        raise NotImplementedError

    @classmethod
    def check_if_supported(cls, *args, **kwargs):
        try:
            fdsw_obj = cls(*args, **kwargs)
            running_sw_version_name = fdsw_obj.swm.get_running_sw_version_name()
            if fdsw_obj.VERSION_NAME in running_sw_version_name:
                return fdsw_obj
            else:
                fdsw_obj.disconnect()
                time.sleep(1)  # timeout to allow jsilib to close connection
                return None
        except (ClientAuthenticationFailed, ClientRequestFailed,
                ClientConnectionFailed, TypeError, AttributeError, socket_error, InvalidStatusCode):
            return None

    def disconnect(self):
        self._client.disconnect()

    def __getattr__(self, item):
        return FunctionalityNotImplemented(category=item, version=self.VERSION_NAME)
